sp_widget.client_script:
api.controller = function($scope, $window) {

    var c = this;


    /*
     * =====================================================
     * INITIAL DATA
     * =====================================================
     */

    c.search = "";

    c.branchFilter = "";

    c.cgpaFilter = "";

    c.statusFilter = "";


    /*
     * =====================================================
     * BACK TO DASHBOARD
     * =====================================================
     */

    c.backToDashboard = function() {

        $window.location.href =
            "?id=recruiter_dashboard";

    };


    /*
     * =====================================================
     * VIEW CANDIDATE
     * =====================================================
     */

    c.viewCandidate = function(candidate) {

        if (!candidate || !candidate.sys_id) {
            return;
        }

        $window.location.href =
            "?id=campus360_recruiter_candidate_details" +
            "&sys_id=" +
            encodeURIComponent(candidate.sys_id);

    };


    /*
     * =====================================================
     * SEARCH + FILTER
     * =====================================================
     */

    c.filterCandidate = function(candidate) {

        if (!candidate) {
            return false;
        }


        /*
         * SEARCH
         */

        if (c.search) {

            var searchText =
                c.search.toLowerCase().trim();

            var name =
                (candidate.name || "").toLowerCase();

            var studentId =
                (candidate.student_id || "").toLowerCase();

            var branch =
                (candidate.branch || "").toLowerCase();

            var skills =
                (candidate.skills || []).join(" ").toLowerCase();

            var email =
                (candidate.email || "").toLowerCase();


            var matchesSearch =
                name.indexOf(searchText) !== -1 ||
                studentId.indexOf(searchText) !== -1 ||
                branch.indexOf(searchText) !== -1 ||
                skills.indexOf(searchText) !== -1 ||
                email.indexOf(searchText) !== -1;


            if (!matchesSearch) {
                return false;
            }

        }


        /*
         * BRANCH FILTER
         */

        if (c.branchFilter) {

            if (candidate.branch !== c.branchFilter) {
                return false;
            }

        }


        /*
         * CGPA FILTER
         */

        if (c.cgpaFilter) {

            var cgpa =
                parseFloat(candidate.cgpa || 0);

            var minimum =
                parseFloat(c.cgpaFilter);

            if (cgpa < minimum) {
                return false;
            }

        }


        /*
         * PLACEMENT STATUS
         */

        if (c.statusFilter) {

            if (
                candidate.placement_status !==
                c.statusFilter
            ) {

                return false;

            }

        }


        return true;

    };


    /*
     * =====================================================
     * GET UNIQUE BRANCHES
     * =====================================================
     */

    c.getBranches = function() {

        var branches = [];

        if (!c.data || !c.data.candidates) {
            return branches;
        }


        c.data.candidates.forEach(function(candidate) {

            if (
                candidate.branch &&
                branches.indexOf(candidate.branch) === -1
            ) {

                branches.push(candidate.branch);

            }

        });


        branches.sort();

        return branches;

    };


    /*
     * =====================================================
     * RESULT COUNT
     * =====================================================
     */

    c.getFilteredCount = function() {

        if (!c.data || !c.data.candidates) {
            return 0;
        }

        var count = 0;

        c.data.candidates.forEach(function(candidate) {

            if (c.filterCandidate(candidate)) {
                count++;
            }

        });

        return count;

    };


    /*
     * =====================================================
     * CLEAR FILTERS
     * =====================================================
     */

    c.clearFilters = function() {

        c.search = "";

        c.branchFilter = "";

        c.cgpaFilter = "";

        c.statusFilter = "";

    };


    /*
     * =====================================================
     * REFRESH
     * =====================================================
     */

    c.refresh = function() {

        c.server.update();

    };


};

sp_widget.css:
.talent-pool-page {
    min-height: 100vh;
    padding: 32px;
    background: #eef2f7;
    font-family: Arial, sans-serif;
    color: #17213a;
}


/* =========================================
   HEADER
   ========================================= */

.page-header {
    background: linear-gradient(
        135deg,
        #182848,
        #3b4cc0
    );

    color: white;

    padding: 28px 32px;

    border-radius: 16px;

    display: flex;
    justify-content: space-between;
    align-items: center;

    margin-bottom: 20px;

    box-shadow:
        0 8px 24px rgba(30, 45, 100, 0.18);
}


.eyebrow {
    font-size: 11px;
    font-weight: 700;

    letter-spacing: 1.5px;

    color: #cdd6ff;

    margin-bottom: 8px;
}


.page-header h1 {
    margin: 0;

    font-size: 28px;

    font-weight: 700;

    color: white;
}


.page-header p {
    margin: 8px 0 0;

    font-size: 13px;

    color: #d9dff5;
}


/* =========================================
   BACK BUTTON
   ========================================= */

.back-btn {
    border: 1px solid rgba(255,255,255,0.5);

    background: rgba(255,255,255,0.1);

    color: white;

    padding: 11px 18px;

    border-radius: 9px;

    cursor: pointer;

    font-size: 12px;

    transition: 0.2s;
}


.back-btn:hover {
    background: white;
    color: #3b4cc0;
}


/* =========================================
   SEARCH
   ========================================= */

.search-panel {
    background: white;

    padding: 18px;

    border-radius: 14px;

    display: flex;

    gap: 12px;

    margin-bottom: 14px;

    border: 1px solid #dce2ec;

    box-shadow:
        0 4px 14px rgba(30,45,80,0.06);
}


.search-box {
    flex: 1;

    display: flex;

    align-items: center;

    border: 1px solid #d6dce8;

    border-radius: 9px;

    padding: 0 14px;

    background: #f8faff;
}


.search-box span {
    color: #667085;

    font-size: 21px;

    margin-right: 10px;
}


.search-box input {
    width: 100%;

    border: none;

    outline: none;

    background: transparent;

    padding: 12px 0;

    font-size: 13px;

    color: #27324a;
}


.search-btn {
    background: #4658d8;

    color: white;

    border: none;

    border-radius: 9px;

    padding: 0 26px;

    cursor: pointer;

    font-size: 13px;

    font-weight: 600;

    transition: 0.2s;
}


.search-btn:hover {
    background: #3547c5;

    transform: translateY(-1px);
}


/* =========================================
   FILTERS
   ========================================= */

.filters {
    background: white;

    padding: 18px;

    border-radius: 14px;

    display: flex;

    gap: 18px;

    margin-bottom: 22px;

    border: 1px solid #dce2ec;

    box-shadow:
        0 4px 14px rgba(30,45,80,0.05);
}


.filters > div {
    width: 220px;
}


.filters label {
    display: block;

    color: #667085;

    font-size: 11px;

    font-weight: 600;

    margin-bottom: 7px;
}


.filters select {
    width: 100%;

    border: 1px solid #d6dce8;

    border-radius: 8px;

    padding: 10px;

    background: #f9fafc;

    color: #27324a;

    font-size: 13px;

    outline: none;
}


.filters select:focus {
    border-color: #5368d8;

    box-shadow:
        0 0 0 3px rgba(83,104,216,0.1);
}


/* =========================================
   RESULT COUNT
   ========================================= */

.result-header {
    margin-bottom: 14px;

    color: #667085;

    font-size: 13px;
}


.result-header strong {
    color: #17213a;

    font-size: 18px;

    margin-right: 4px;
}


/* =========================================
   GRID
   ========================================= */

.candidate-grid {
    display: grid;

    grid-template-columns:
        repeat(3, minmax(0, 1fr));

    gap: 18px;
}


/* =========================================
   CARD
   ========================================= */

.candidate-card {
    background: white;

    border-radius: 15px;

    padding: 20px;

    border: 1px solid #dce2ec;

    box-shadow:
        0 4px 14px rgba(30,45,80,0.06);

    transition:
        transform 0.2s,
        box-shadow 0.2s,
        border-color 0.2s;
}


.candidate-card:hover {
    transform: translateY(-4px);

    border-color: #b8c2f5;

    box-shadow:
        0 10px 25px rgba(30,45,80,0.12);
}


/* =========================================
   TOP
   ========================================= */

.candidate-top {
    display: flex;

    align-items: center;

    gap: 12px;

    margin-bottom: 18px;
}


.avatar {
    width: 48px;

    height: 48px;

    border-radius: 12px;

    background:
        linear-gradient(
            135deg,
            #4658d8,
            #6979e8
        );

    color: white;

    display: flex;

    align-items: center;

    justify-content: center;

    font-weight: 700;

    font-size: 14px;

    box-shadow:
        0 5px 12px rgba(70,88,216,0.25);
}


.candidate-name h3 {
    margin: 0;

    color: #17213a;

    font-size: 15px;

    font-weight: 700;
}


.candidate-name p {
    margin: 4px 0 0;

    color: #7a8498;

    font-size: 11px;
}


/* =========================================
   INFO
   ========================================= */

.candidate-info {
    display: grid;

    grid-template-columns:
        1fr 1fr;

    gap: 14px;

    margin-bottom: 17px;

    padding-bottom: 16px;

    border-bottom:
        1px solid #edf0f5;
}


.candidate-info label {
    display: block;

    color: #98a2b3;

    font-size: 10px;

    margin-bottom: 5px;

    text-transform: uppercase;

    letter-spacing: .4px;
}


.candidate-info span {
    color: #29344e;

    font-size: 13px;

    font-weight: 600;
}


/* =========================================
   SKILLS
   ========================================= */

.skills {
    display: flex;

    flex-wrap: wrap;

    gap: 6px;

    min-height: 30px;

    margin-bottom: 18px;
}


.skill {
    background: #edf0ff;

    color: #4658d8;

    padding: 5px 9px;

    border-radius: 6px;

    font-size: 10px;

    font-weight: 600;
}


.skill-more {
    color: #7a8498;

    font-size: 10px;

    padding: 5px 3px;
}


/* =========================================
   FOOTER
   ========================================= */

.candidate-footer {
    display: flex;

    align-items: center;

    justify-content: space-between;
}


.placement-status {
    padding: 5px 9px;

    border-radius: 6px;

    font-size: 10px;

    font-weight: 600;

    background: #fff4e5;

    color: #c77700;
}


.placement-status.placed {
    background: #e8f7ef;

    color: #188653;
}


.placement-status.not-placed {
    background: #fff4e5;

    color: #c77700;
}


.view-btn {
    border: 1px solid #d7dcf8;

    background: #f1f3ff;

    color: #4658d8;

    padding: 8px 12px;

    border-radius: 7px;

    cursor: pointer;

    font-size: 11px;

    font-weight: 600;

    transition: 0.2s;
}


.view-btn:hover {
    background: #4658d8;

    color: white;

    border-color: #4658d8;
}


/* =========================================
   EMPTY STATE
   ========================================= */

.empty-state {
    grid-column: 1 / -1;

    background: white;

    border-radius: 15px;

    padding: 70px 20px;

    text-align: center;

    border: 1px solid #dce2ec;
}


.empty-icon {
    font-size: 35px;

    margin-bottom: 12px;
}


.empty-state h3 {
    margin: 0 0 8px;

    color: #17213a;
}


.empty-state p {
    margin: 0;

    color: #8a94a7;

    font-size: 13px;
}


/* =========================================
   RESPONSIVE
   ========================================= */

@media (max-width: 1100px) {

    .candidate-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }

}


@media (max-width: 750px) {

    .talent-pool-page {
        padding: 15px;
    }


    .page-header {
        flex-direction: column;

        align-items: flex-start;

        gap: 18px;
    }


    .search-panel {
        flex-direction: column;
    }


    .search-btn {
        padding: 12px;
    }


    .filters {
        flex-direction: column;
    }


    .filters > div {
        width: 100%;
    }


    .candidate-grid {
        grid-template-columns: 1fr;
    }

}

sp_widget.script:
(function() {

    data.candidates = [];

    var students = new GlideRecord('x_snc_campus360_student_master');

    students.orderBy('student_name');
    students.query();

    while (students.next()) {

        var candidate = {};

        candidate.sys_id = students.getUniqueValue();

        candidate.name = students.getValue('student_name') || 'Unknown Student';

        candidate.student_id = students.getValue('student_id') || '';

        candidate.branch = students.getValue('branch') || '';

        candidate.cgpa = students.getValue('cgpa') || '';

        candidate.placement_status =
            students.getValue('placement_status') || 'Not Placed';

        candidate.profile_status =
            students.getValue('profile_status') || '';

        candidate.email =
            students.getValue('email') || '';

        /*
         * INITIALS
         */

        var nameParts = candidate.name.trim().split(/\s+/);

        if (nameParts.length >= 2) {

            candidate.initials =
                nameParts[0].charAt(0).toUpperCase() +
                nameParts[nameParts.length - 1].charAt(0).toUpperCase();

        } else {

            candidate.initials =
                candidate.name.substring(0, 2).toUpperCase();

        }


        /*
         * GET STUDENT SKILLS
         */

        candidate.skills = [];

        var skillGR =
            new GlideRecord('x_snc_campus360_student_skills');

        skillGR.addQuery('student', students.getUniqueValue());

        skillGR.orderBy('skill_name');

        skillGR.query();

        while (skillGR.next()) {

            var skillName =
                skillGR.getValue('skill_name');

            if (skillName) {

                candidate.skills.push(skillName);

            }

        }


        /*
         * ADD CANDIDATE
         */

        data.candidates.push(candidate);

    }


})();
